    43  inline static
    44  void _gnutls_free_datum(gnutls_datum_t * dat)
    45  {
    46          if (dat == NULL)
    47                  return;
    48
    49          if (dat->data != NULL)
    50                  gnutls_free(dat->data);
    51
    52          dat->data = NULL;
    53          dat->size = 0;
    54  }
    55
    56  inline static
    57  void _gnutls_free_temp_key_datum(gnutls_datum_t * dat)
    58  {
    59          if (dat->data != NULL) {
    60                  zeroize_temp_key(dat->data, dat->size);
    61                  gnutls_free(dat->data);
    62          }
    63
    64          dat->data = NULL;
    65          dat->size = 0;
    66  }
    67
    68  inline static
    69  void _gnutls_free_key_datum(gnutls_datum_t * dat)
    70  {
    71          if (dat->data != NULL) {
    72                  zeroize_key(dat->data, dat->size);
    73                  gnutls_free(dat->data);
    74          }
